import numpy as np

def get_knight_moves(r, c):
    """Returns valid knight moves from (r, c) on an 8x8 board."""
    moves = []
    deltas = [
        (2, 1), (2, -1), (-2, 1), (-2, -1),
        (1, 2), (1, -2), (-1, 2), (-1, -2)
    ]
    for dr, dc in deltas:
        nr, nc = r + dr, c + dc
        if 0 <= nr < 8 and 0 <= nc < 8:
            moves.append((nr, nc))
    return moves

def get_queen_attacks(r, c):
    """Returns squares attacked by a queen at (r, c) on an 8x8 board."""
    attacks = set()
    N = 8
    # Horizontal and Vertical
    for i in range(N):
        if i != c: attacks.add((r, i))
        if i != r: attacks.add((i, c))
    # Diagonals
    for i in range(N):
        for j in range(N):
            if i == r or j == c:
                continue
            if abs(i - r) == abs(j - c):
                attacks.add((i, j))
    return attacks

